package com.devskiller.calculator;

/**
 * Simple calculator with basic arithmetic operations.
 *
 * Based on the Devskiller sample Maven calculator project
 * (https://github.com/Devskiller/devskiller-sample-maven-calculator).
 *
 * BUG: The divide method does not handle division by zero.
 * It will throw an ArithmeticException instead of the expected
 * IllegalArgumentException when the divisor is zero.
 */
public class Calculator {

    public int add(int a, int b) {
        return a + b;
    }

    public int subtract(int a, int b) {
        return a - b;
    }

    public int multiply(int a, int b) {
        return a * b;
    }

    /**
     * Divides a by b.
     * BUG: No division-by-zero check - throws ArithmeticException
     * instead of IllegalArgumentException.
     */
    public int divide(int a, int b) {
        return a / b;
    }
}

