package com.devskiller.calculator;

import org.junit.Test;
import static org.junit.Assert.*;

/**
 * JUnit tests for Calculator.
 *
 * Based on the Devskiller sample Maven calculator project
 * (https://github.com/Devskiller/devskiller-sample-maven-calculator).
 *
 * testDivideByZero will FAIL until the bug in Calculator.divide() is fixed.
 * The divide method must throw IllegalArgumentException with message
 * "Cannot divide by zero" when the divisor is 0.
 */
public class CalculatorTest {

    private Calculator calculator = new Calculator();

    @Test
    public void testAdd() {
        assertEquals(5, calculator.add(2, 3));
    }

    @Test
    public void testSubtract() {
        assertEquals(1, calculator.subtract(3, 2));
    }

    @Test
    public void testMultiply() {
        assertEquals(6, calculator.multiply(2, 3));
    }

    @Test
    public void testDivide() {
        assertEquals(5, calculator.divide(10, 2));
    }

    @Test
    public void testDivideByZero() {
        try {
            calculator.divide(10, 0);
            fail("Should throw IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Cannot divide by zero", e.getMessage());
        }
    }
}
